package com.example.spring_blog.payment;import com.example.spring_blog.error.Exception400;import lombok.Data;public class PaymentRequest {    @Data    public static class PrepareDTO{        private Integer amount;        public void validate() {            if (amount == null || amount < 1000) {                throw new Exception400("최소 충전금액은 1,000 포인트입니다.");            }            if (amount == null || amount > 100000) {                throw new Exception400("최대 충전금액은 100,000 포인트입니다.");            }        }    }    @Data    public static class CompleteDTO {        private String paymentId;        public void validate() {            if (paymentId == null || paymentId.isBlank()) {                throw new Exception400("결제건 식별자가 필요합니다.");            }        }    }}